const LEGACY_IMPORT =
  "TEMPORARY. Imports a module listed in its app's `legacyUiLint({ modules })`. Exit condition: " +
  "migrate the file to Lumen, then delete this entry.";

/**
 * @param {string} flag
 * @returns {string} the reason of a folder that the flag's cleanup deletes
 */
function dyingWithFlag(flag) {
  return (
    `TEMPORARY. Legacy screens replaced behind the ${flag} feature flag. Exit condition: the ` +
    "flag's cleanup deletes them, then delete this entry."
  );
}

